var KEYFRAMES = "@keyframes sway{0%,100%{transform:rotate(-7deg)}50%{transform:rotate(7deg)}}@keyframes rock{0%,100%{transform:rotate(-.5deg)}50%{transform:rotate(.5deg)}}@keyframes drift{from{background-position-x:0}to{background-position-x:-400px}}@keyframes glow{0%,100%{opacity:.55}50%{opacity:1}}@keyframes rise{0%{transform:translateY(0);opacity:0}15%{opacity:.9}100%{transform:translateY(-420px);opacity:0}}@keyframes fall{0%{transform:translate(0,-40px) rotate(0);opacity:0}10%{opacity:1}100%{transform:translate(90px,720px) rotate(540deg);opacity:0}}@keyframes firefly{0%,100%{transform:translate(0,0);opacity:.2}25%{transform:translate(18px,-14px);opacity:1}50%{transform:translate(-10px,-30px);opacity:.3}75%{transform:translate(12px,-12px);opacity:1}}@keyframes spin{to{transform:rotate(360deg)}}@keyframes lit{0%,100%{opacity:.7}45%{opacity:1}60%{opacity:.5}}@keyframes fogx{from{transform:translateX(-90px)}to{transform:translateX(90px)}}@keyframes dash{0%{stroke-dashoffset:480}60%,100%{stroke-dashoffset:0}}@keyframes shoot{0%{transform:translate(0,0) rotate(24deg);opacity:0}8%{opacity:1}30%,100%{transform:translate(620px,280px) rotate(24deg);opacity:0}}@keyframes flick{0%,100%{transform:scale(1,1) translateX(0);opacity:.95}30%{transform:scale(.9,1.12) translateX(1px);opacity:1}60%{transform:scale(1.06,.92) translateX(-1px);opacity:.85}}@keyframes bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-12px)}}@keyframes fly{0%{transform:translate(-80px,0)}25%{transform:translate(260px,-26px)}50%{transform:translate(620px,10px)}75%{transform:translate(940px,-22px)}100%{transform:translate(1380px,0)}}@keyframes smoke{0%{transform:translate(0,0) scale(.6);opacity:0}20%{opacity:.5}100%{transform:translate(24px,-150px) scale(2);opacity:0}}@keyframes flap{0%,100%{transform:scaleY(1)}50%{transform:scaleY(.35)}}@keyframes nb-tw{0%,100%{opacity:.2}50%{opacity:1}}@keyframes nb-ff{0%,100%{transform:translate(0,0);opacity:.15}25%{transform:translate(20px,-16px);opacity:1}50%{transform:translate(-12px,-34px);opacity:.3}75%{transform:translate(14px,-14px);opacity:1}}@keyframes nb-up{0%{transform:translate(0,0);opacity:0}12%{opacity:1}100%{transform:translate(var(--dx,20px),-560px);opacity:0}}@keyframes nb-snow{0%{transform:translate(0,-30px);opacity:0}10%{opacity:.9}100%{transform:translate(var(--dx,60px),800px);opacity:.2}}@keyframes nb-mist{from{transform:translateX(-140px)}to{transform:translateX(140px)}}@keyframes nb-ray{0%,100%{opacity:.2}50%{opacity:.55}}@keyframes nb-aur{0%,100%{transform:translateX(-70px) scaleY(1);opacity:.5}50%{transform:translateX(70px) scaleY(1.3);opacity:.95}}@keyframes nb-sway{0%,100%{transform:rotate(-1.4deg)}50%{transform:rotate(1.4deg)}}";
