  taverne:{table:'#3a2413',border:'#6b4a2f',lane:'#2c1a0d',line:'#8a6a42',gold:'#f2b530',panel:'#12090a',btn:'#7a3b1d'},
  bateau:{table:'repeating-linear-gradient(90deg,#5a4026 0 118px,#3e2a16 118px 122px)',border:'#8a6a3e',lane:'#3b2a18',line:'#b99a5e',gold:'#e6b84a',panel:'#101820',btn:'#a3321f'},
  village:{table:'repeating-linear-gradient(90deg,#6a4a2f 0 150px,#533a24 150px 154px)',border:'#8a6a3e',lane:'#4a3322',line:'#c9a46a',gold:'#e0a84a',panel:'#1a1210',btn:'#9a3b22'},
