  ecole:{table:'repeating-linear-gradient(0deg,rgba(201,166,74,.12) 0 1px,transparent 1px 44px),repeating-linear-gradient(90deg,rgba(201,166,74,.12) 0 1px,transparent 1px 44px),#2a2350',border:'#c9a64a',lane:'#1e1a3c',line:'#a8934a',gold:'#e8c872',panel:'#0c0920',btn:'#5a2a8a'},
  carte:{table:'#9a7a46',border:'#4a2f12',lane:'#6e4f27',line:'#6a4a22',gold:'#e8c872',panel:'#1a120a',btn:'#8a3b1d'},
  marbre:{table:'#1a1722',border:'#b08d3a',lane:'#0e0c13',line:'#b08d3a',gold:'#e6c15a',panel:'#0d0b12',btn:'#7a5a1a'},
  runes:{table:'#1c2026',border:'#3fa8b8',lane:'#0e1216',line:'#4fc0d0',gold:'#8fe8f2',panel:'#0a0e12',btn:'#1f6a78'},
